content:
:root {
  /* プライマリカラー */
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  /* 背景・カードカラー */
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  /* テキストカラー */
  --text-main: #1e293b;
  --text-muted: #64748b;
  /* ボーダー・テーブルカラー */
  --border-color: #e2e8f0;
  --table-hover: #f1f5f9;
  /* その他（角丸・影） */
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 900px;
  margin: 0 auto;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  overflow: hidden;
}

.header {
  margin-bottom: 24px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 16px;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.controls {
  margin-bottom: 20px;
  display: flex;
  justify-content: flex-start;
  align-items: center;
}

.search-input {
  width: 100%;
  max-width: 320px;
  padding: 10px 14px;
  font-size: 0.95rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.search-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.35);
}

.table-container {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
  min-width: 500px;
}

.employee-table th,
.employee-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.th-sortable {
  background-color: #f8fafc;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s, color 0.2s;
  white-space: nowrap;
}

.th-sortable:hover {
  background-color: #e2e8f0;
  color: var(--text-main);
}

.td-cell {
  color: var(--text-main);
}

.employee-table tbody tr {
  transition: background-color 0.15s;
}

.employee-table tbody tr:hover {
  background-color: var(--table-hover);
}

.no-results {
  text-align: center;
  padding: 32px;
  color: var(--text-muted);
  font-style: italic;
}

@media (max-width: 640px) {
  body {
    padding: 10px;
  }

  .app-container {
    padding: 16px;
  }

  .search-input {
    max-width: 100%;
  }

  .employee-table th,
  .employee-table td {
    padding: 10px 8px;
    font-size: 0.85rem;
  }
}

/**
 * 社員情報を表すインターフェース
 */
export interface Employee {
  /** 社員ID */
  id: number;
  /** 氏名 */
  name: string;
  /** 所属部署 */
  department: string;
  /** 年齢 */
  age: number;
  /** メールアドレス（将来の拡張用） */
  email?: string;
  /** 入社日（将来の拡張用） */
  joinedDate?: string;
}

/**
 * 並べ替えの対象となるフィールド
 */
export type SortField = 'name' | 'department' | 'age';

/**
 * 並べ替えの順序（昇順・降順）
 */
export type SortOrder = 'asc' | 'desc';

/**
 * フィルター条件を管理するための型
 */
export interface FilterState {
  /** 検索クエリ（名前による絞り込み） */
  searchQuery: string;
  /** 部署フィルター（将来の拡張用） */
  department?: string;
}

import { useState, useMemo } from 'react';
import { Employee, SortField, SortOrder } from './types';
import './index.css';

const initialEmployees: Employee[] = [
  { id: 1, name: '佐藤 健一', department: '開発部', age: 28 },
  { id: 2, name: '鈴木 美咲', department: '人事部', age: 34 },
  { id: 3, name: '高橋 拓海', department: '営業部', age: 41 },
  { id: 4, name: '田中 葵', department: '開発部', age: 25 },
  { id: 5, name: '伊藤 蓮', department: 'マーケティング部', age: 30 },
  { id: 6, name: '渡辺 さくら', department: '営業部', age: 29 },
  { id: 7, name: '山本 大翔', department: '開発部', age: 37 },
  { id: 8, name: '中村 陽菜', department: '人事部', age: 26 },
  { id: 9, name: '小林 悠真', department: 'マーケティング部', age: 45 },
  { id: 10, name: '加藤 結衣', department: '営業部', age: 32 },
];

export default function App() {
  const [searchQuery, setSearchQuery] = useState('');
  const [sortField, setSortField] = useState<SortField | null>(null);
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    let result = initialEmployees.filter((emp) =>
      emp.name.toLowerCase().includes(query)
    );

    if (sortField) {
      result.sort((a, b) => {
        const aVal = a[sortField];
        const bVal = b[sortField];

        if (typeof aVal === 'string' && typeof bVal === 'string') {
          const comparison = aVal.localeCompare(bVal, 'ja');
          return sortOrder === 'asc' ? comparison : -comparison;
        } else if (typeof aVal === 'number' && typeof bVal === 'number') {
          return sortOrder === 'asc' ? aVal - bVal : bVal - aVal;
        }
        return 0;
      });
    }

    return result;
  }, [searchQuery, sortField, sortOrder]);

  const getAriaSort = (field: SortField) => {
    if (sortField !== field) return 'none';
    return sortOrder === 'asc' ? 'ascending' : 'descending';
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">社員名簿</h1>
      </header>

      <div className="controls">
        <input
          type="text"
          className="search-input"
          placeholder="名前で絞り込み..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      <div className="table-container">
        <table className="employee-table">
          <thead>
            <tr>
              <th 
                className="th-sortable" 
                onClick={() => handleSort('name')}
                aria-sort={getAriaSort('name')}
              >
                名前 {sortField === 'name' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
              </th>
              <th 
                className="th-sortable" 
                onClick={() => handleSort('department')}
                aria-sort={getAriaSort('department')}
              >
                部署 {sortField === 'department' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
              </th>
              <th 
                className="th-sortable" 
                onClick={() => handleSort('age')}
                aria-sort={getAriaSort('age')}
              >
                年齢 {sortField === 'age' ? (sortOrder === 'asc' ? '▲' : '▼') : ''}
              </th>
            </tr>
          </thead>
          <tbody>
            {filteredAndSortedEmployees.length > 0 ? (
              filteredAndSortedEmployees.map((emp) => (
                <tr key={emp.id}>
                  <td className="td-cell">{emp.name}</td>
                  <td className="td-cell">{emp.department}</td>
                  <td className="td-cell">{emp.age}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={3} className="no-results">
                  条件に一致する社員が見つかりませんでした。検索条件を変更してお試しください。
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
